from pathlib import Path
from datetime import datetime, timezone
import collections, difflib, hashlib, html, json, shutil
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
import numpy as np

R=Path('/Users/yp9846/Desktop/PhysLiteBench')
A=R/'results/trajectory-analysis-20261014'
O=R/'output/trajectory-analysis-20261014'
D=json.loads((A/'analysis.json').read_text())
F=json.loads((A/'diagnostic-repairs.json').read_text())
def sha(p): return hashlib.sha256(p.read_bytes()).hexdigest()
def esc(x): return html.escape(str(x))
def label(model, effort):
    name={'gpt-6-luna':'GPT-6 Luna','gpt-5.6-terra':'GPT-5.6 Terra','gpt-6-sol':'GPT-6 Sol','gpt-6-astra':'GPT-6 Astra','deepseek/deepseek-v4.1-flash':'DeepSeek V4.1 Flash'}[model]
    return name+' / '+{'low':'Low','high':'High','xhigh':'Extra High','max':'Max','none':'None'}[effort]

CASES=[
dict(trial='entropy-anomaly__6yBuZGL',title='Fits the friction; leaves the contact population correction at zero',finding='GPT-6 Luna Low implemented weighted least squares and left the entire predictor unchanged. Calibration was accurate, but the conditional contact residence correction was still identically zero.',actions=[(6,'Reads the apparatus and starter.'),(9,'Creates a friction scan.'),(11,'Implements fit(), leaving the physical predictor unchanged.'),(12,'Runs public tests: 2 passed.')],diagnosis='Physical approximation retained. The in-memory population correction reduces the largest hidden-group error from 77.38% to 0.0443% with the fitted friction fixed.',confidence='Confirmed by a targeted diagnostic intervention'),
dict(trial='magnetic-tracer__GAWaaTf',title='Gets density and mean circulation right; misses correlated detector noise',finding='GPT-6 Luna High changed only fit(). The first tilted-generator coefficient stayed diagonal, omitting mixed longitudinal/detector diffusion. Twenty-one of 23 hidden groups were already below tolerance; anisotropic noise and the third cumulant were wrong.',actions=[(6,'Reads README and model.'),(8,'Connects fit() to the supplied fit_friction helper.'),(9,'Runs public tests: 2 passed.')],diagnosis='Physical noise-correlation omission. Noise error was 27.58% and third-cumulant error 101.10%. Restoring the mixed diffusion term gives 0.0316% and 0.0614%, respectively, with no refit.',confidence='Confirmed by a targeted diagnostic intervention'),
dict(trial='single-file-memory__PC6LumP',title='Labels the preparation correctly, but keeps the wrong covariance formula',finding='GPT-5.6 Terra High added input checks and a docstring referring to deterministic preparation. The implemented covariance nevertheless retained the stationary-increment expression. Equal-time calibration cannot distinguish these kernels.',actions=[(6,'Reads the stated preparation and starter.'),(8,'Adds validation, a weighted fit and documentation; preserves the covariance formula.'),(9,'Runs public tests and prints the fitted diffusivity.')],diagnosis='Preparation-dependent two-time memory is missing. The parameter error is 0.00554%; unequal-time group errors are 36.60%, 77.88% and 136.06%. Changing only the covariance formula gives 0.00277% in every group.',confidence='Confirmed by a targeted diagnostic intervention'),
dict(trial='reaction-diffusion__2xoVywU',title='Rewrites transport carefully, but preserves independent initial constituent counts',finding='GPT-5.6 Terra High rewrote the solver and added validation. The final correlate() still multiplied the relaxation propagator by diag(totals), even though it computed the charge-conditioned susceptibility for the relaxation rate.',actions=[(9,'Checks the transport reduction numerically.'),(10,'Starts a full rewrite of model.py.'),(12,'Writes the replacement implementation.'),(13,'Runs public tests and transport checks.'),(15,'Adds the zero-time prediction branch.'),(16,'Reruns public tests and further numerical checks.')],diagnosis='Wrong equilibrium initial covariance. Mean transport errors remain small, but fluctuation-group errors are 42.15–59.41%. Replacing diag(totals) with the already-computed susceptibility reduces those errors to at most 0.00308%.',confidence='Confirmed by a targeted diagnostic intervention'),
dict(trial='hierarchical-glass-overlaps__2Xjntmr',title='Refines the warm fit, without changing the frozen hierarchy probabilities',finding='GPT-5.6 Terra High added a robust width fit and extra validation, while predict() and its independent-coordinate probability calculation remained unchanged.',actions=[(8,'Computes the weighted warm-regime fit.'),(9,'Implements fit().'),(10,'Runs public tests.'),(11,'Refines numerical handling of weights.'),(13,'Adds calibration-input validation.'),(14,'Runs public tests again.')],diagnosis='Source inspection supports a missing correlation between parent selection and descendant weights. Parent collisions are accurate, but state/joint-group errors range from 19.79% to 48.99%. This case was not independently repaired in this analysis.',confidence='Supported by final code, metrics and the frozen task derivation'),
dict(trial='ring-current-fluctuations__HHRAGEs',title='A completed DeepSeek solution extrapolates the homogeneous branch',finding='DeepSeek High checked several empirical fits on the low-field calibration data, then submitted the homogeneous quadratic current formula throughout the domain.',actions=[(4,'Reads the public apparatus and starter.'),(6,'Inspects calibration ranges.'),(7,'Groups calibration observations.'),(8,'Fits the known homogeneous quadratic feature.'),(9,'Tests a broader quadratic fit.'),(10,'Tests another polynomial feature set.'),(11,'Writes the final homogeneous predictor and runs public tests: 2 passed.'),(12,'Checks the interface and fitted parameter.')],diagnosis='Physical branch selection is missing: the submitted formula has no modulated-density branch. Calibration chi-square is 0.955 and parameter error 0.00179%, but field-10 and field-12 prediction errors are 23.07% and 42.35%.',confidence='Supported by final code, metrics and the frozen task derivation'),
dict(trial='entropy-anomaly__NUsFpY4',title='Explores and simulates until the deadline, without saving a model change',finding='DeepSeek High issued analytical checks, parameter scans and long Monte Carlo simulations in temporary scripts. At the 600-second limit, saved model.py was byte-identical to the unfinished starter.',actions=[(4,'Reads README and starter.'),(7,'Scans calibration residuals.'),(8,'Checks a uniform limit.'),(13,'Runs a simulation with a four-million-step default.'),(14,'Runs another simulation with two million steps.'),(16,'Creates a longer temporary simulation script.'),(17,'Issues a sleep command while work runs.'),(18,'Polls the running computation.'),(22,'Polls another computation.'),(24,'Creates a second temporary simulation implementation before timeout.')],diagnosis='Observed failure to deliver within the time budget. No physical-error conclusion is justified from this unfinished submission. The log does not establish how much of the timeout came from model latency versus tool computation.',confidence='Directly observed timeout and unchanged submitted source'),
dict(trial='ring-current-fluctuations__q7QawzD',title='Replaces the model with an expression that fails even calibration',finding='GPT-6 Luna Low replaced the predictor with a claimed parametric formula. At zero field it returns 2 sin²(bias/4), whereas the frozen task’s homogeneous limit is bias²/4. The recorded tools contain no test run after the final replacement.',actions=[(7,'Reads the apparatus, source and calibration.'),(8,'Summarizes calibration by input setting.'),(11,'Deletes the starter implementation.'),(12,'Writes the replacement parametric expression.')],diagnosis='Mathematical/model-form error, caught by calibration itself: reduced chi-square is 20,916 and parameter error 28.07%. This is not a hidden-only generalization failure.',confidence='Direct source discrepancy and failed calibration; no repair performed'),
dict(trial='entropy-anomaly__9cN3Afs',title='Successful comparison: changes the missing population equation before checking tests',finding='GPT-6 Sol Low solved the first-order contact continuity equation and supplied the fit in the same patch. Its saved submission passed every verifier check.',actions=[(6,'Reads apparatus and starter.'),(7,'Reads public tests and calibration.'),(8,'Restores the conditional contact population equation and implements fit().'),(9,'Runs public tests.'),(10,'Checks the fitted parameter and additional physical settings.')],diagnosis='The successful code changes the same term isolated by the failed Luna submission’s diagnostic repair. The maximum hidden-group error is 0.0443%. This comparison is observational; the fixed-parameter repair supplies the more direct evidence.',confidence='Completed passing comparison plus agreement with diagnostic intervention'),
]

def main():
    O.mkdir(parents=True,exist_ok=True)
    order={'gpt-6-luna':0,'gpt-5.6-terra':1,'deepseek/deepseek-v4.1-flash':2,'gpt-6-sol':3,'gpt-6-astra':4}
    eo={'low':0,'high':1,'xhigh':2,'max':2}
    panels=sorted([s for s in D['summary'] if s['complete_panel']],key=lambda s:(order[s['model']],eo[s['effort']]))
    cats=[('pass','Completed pass','#16816a'),('hidden_prediction_only','Prediction-only failure','#e6a348'),('other_verification_failure','Other verification failure','#ce5b50'),('timeout','600 s timeout','#8070af'),('other_execution_error','Other execution error','#9ca8b6')]
    plt.rcParams.update({'font.family':'DejaVu Sans','font.size':11,'axes.spines.top':False,'axes.spines.right':False})
    fig,ax=plt.subplots(figsize=(14,9.8));fig.subplots_adjust(left=.27,right=.95,top=.82,bottom=.15)
    y=np.arange(len(panels));left=np.zeros(len(panels))
    for key,name,color in cats:
        v=np.array([s['outcomes'].get(key,0) for s in panels]);ax.barh(y,v,left=left,color=color,height=.71,label=name)
        for j,n in enumerate(v):
            if n:ax.text(left[j]+n/2,j,str(n),ha='center',va='center',fontsize=9,color='white' if key=='pass' else '#152030',fontweight='bold')
        left+=v
    assert all(left==39)
    ax.set_yticks(y,[label(s['model'],s['effort']) for s in panels]);ax.invert_yaxis();ax.set_xlim(0,39);ax.set_xticks([0,3,9,15,21,27,33,39]);ax.set_xlabel('Attempts (39 per model and effort)');ax.set_axisbelow(True);ax.xaxis.grid(alpha=.18)
    for yline in [2.5,5.5,8.5,11.5]:ax.axhline(yline,color='#d7dee7',lw=.8)
    fig.suptitle('Where the no-hint attempts stopped',x=.06,y=.97,ha='left',fontsize=25,fontweight='bold',color='#152030')
    fig.text(.06,.919,'13 frozen physics tasks · 3 repeats · 15 complete model–effort settings · 585 attempts',fontsize=13,color='#506074')
    fig.legend(*ax.get_legend_handles_labels(),loc='upper left',bbox_to_anchor=(.055,.894),ncol=3,frameon=False,fontsize=10.5)
    fig.text(.06,.065,'Prediction-only failure: normal completion, calibration and parameter checks pass; only hidden prediction checks fail.\nExecution errors are separate from physics diagnosis. Three partial DeepSeek None attempts are retained outside this chart.',fontsize=10.5,color='#506074',linespacing=1.55)
    for ext in ['png','pdf','svg']:fig.savefig(O/f'failure-breakdown.{ext}',dpi=180,facecolor='white')
    plt.close(fig)

    fig,ax=plt.subplots(figsize=(13,5.5));fig.subplots_adjust(left=.27,right=.9,top=.72,bottom=.2)
    names=['Entropy anomaly\nGPT-6 Luna Low','Magnetic tracer\nGPT-6 Luna High','Single-file memory\nGPT-5.6 Terra High','Reaction–diffusion\nGPT-5.6 Terra High']
    before=[100*max(x['before'].values()) for x in F['cases']];after=[100*max(x['after'].values()) for x in F['cases']]
    for i,(b,a) in enumerate(zip(before,after)):
        ax.plot([a,b],[i,i],color='#c6d0da',lw=3);ax.scatter(b,i,s=80,color='#ce5b50',zorder=3);ax.scatter(a,i,s=80,color='#16816a',zorder=3)
        ax.text(b*1.15,i,f'{b:.2f}%',va='center',fontsize=10);ax.text(a/1.2,i,f'{a:.4f}%',ha='right',va='center',fontsize=10)
    ax.axvspan(4,5,color='#8793a2',alpha=.16)
    ax.text(4.47,-.35,'4–5% limits',ha='center',va='bottom',fontsize=9,color='#506074')
    ax.set_xscale('log');ax.set_xlim(.0008,300);ax.set_yticks(range(4),names);ax.invert_yaxis();ax.set_xlabel('Largest group prediction error (%) · logarithmic scale');ax.xaxis.grid(alpha=.2)
    fig.suptitle('Four isolated physics corrections explain four failures',x=.045,y=.97,ha='left',fontsize=22,fontweight='bold',color='#152030')
    fig.text(.045,.86,'Red: original submission · Green: diagnostic correction · Fitted parameter held fixed',fontsize=12,color='#506074')
    fig.text(.045,.055,'Analyst-provided, post-hoc calculations; no new model attempts and no changes to recorded rewards.\nAll hidden groups evaluated except reaction–diffusion, where the three fluctuation groups were evaluated.',fontsize=10,color='#506074')
    for ext in ['png','pdf','svg']:fig.savefig(O/f'diagnostic-repairs.{ext}',dpi=180,facecolor='white')
    plt.close(fig)

    case_html=[]
    enriched=[]
    for case in CASES:
        r=next(r for r in D['trials'] if r['trial']==case['trial']);p=R/r['path'];dest=A/'cases'/r['trial'];dest.mkdir(parents=True,exist_ok=True)
        for rel in ['artifacts/app/model.py','verifier/metrics.json','verifier/test-stdout.txt','verifier/reward.txt']:
            if (p/rel).exists():shutil.copy2(p/rel,dest/Path(rel).name)
        starter=(p.parent/'frozen-task/environment/model.py').read_text().splitlines(True);final=(p/'artifacts/app/model.py').read_text().splitlines(True)
        (dest/'model.diff').write_text(''.join(difflib.unified_diff(starter,final,fromfile='frozen-starter/model.py',tofile='submitted/model.py')))
        byid={s['step_id']:s for s in r['tool_steps']}
        actions=[]
        for step,description in case['actions']:
            assert step in byid,(r['trial'],step)
            actions.append(dict(step_id=step,timestamp=byid[step]['timestamp'],action=description))
        reviewed=dict(case,actions=actions,model=r['model'],effort=r['reasoning_effort'],task=r['task'],agent_seconds=r['agent_seconds'],exception_type=r['exception_type'],source_path=r['path'],source_sha256=r['source_sha256'],trajectory_sha256=r['trajectory_sha256'],evidence={p.name:sha(p) for p in dest.iterdir() if p.is_file() and p.name != 'review.json'})
        enriched.append(reviewed)
        (dest/'review.json').write_text(json.dumps(reviewed,indent=2)+'\n')
        links=' · '.join(f'<a href="../../results/trajectory-analysis-20261014/cases/{r["trial"]}/{f}">{f}</a>' for f in ['model.py','model.diff','metrics.json','review.json'] if (dest/f).exists())
        acts=''.join(f'<li><b>Step {a["step_id"]}</b> · {esc(a["timestamp"])} — {esc(a["action"])}</li>' for a in actions)
        case_html.append(f'<article><p class="eyebrow">{esc(label(r["model"],r["reasoning_effort"]))} · {esc(r["task"])} · {r["agent_seconds"]:.1f} s</p><h3>{esc(case["title"])}</h3><p>{esc(case["finding"])}</p><p><b>Failure location / result:</b> {esc(case["diagnosis"])}</p><p class="muted">{esc(case["confidence"])}</p><details><summary>Recorded tool-action sequence and evidence</summary><ol>{acts}</ol><p>{links}</p><code>{esc(r["trial"])}</code></details></article>')
    (A/'case-reviews.json').write_text(json.dumps(enriched,indent=2)+'\n')
    tr=''
    for s in panels:
        c=s['outcomes'];tr+=f'<tr><td>{esc(label(s["model"],s["effort"]))}</td>'+''.join(f'<td>{c.get(k,0)}</td>' for k,_,_ in cats)+f'<td>{s["fit_only_hidden_failures"]}</td><td>{s["unchanged_starter"]}</td></tr>'
    repair_rows=''.join(f'<tr><td>{esc(r["task"])}</td><td>{100*max(r["before"].values()):.2f}%</td><td>{100*max(r["after"].values()):.5f}%</td><td>{esc(r["intervention"])}</td></tr>' for r in F['cases'])
    report=f'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>No-hint trajectory analysis — PhysLiteBench</title><style>
body{{font:16px/1.65 system-ui,-apple-system,sans-serif;color:#1b293b;background:#f3f6fa;margin:0}}main{{max-width:1120px;margin:auto;padding:42px 24px 80px}}h1{{font-size:38px;line-height:1.2;max-width:950px}}h2{{margin-top:46px;font-size:26px}}h3{{font-size:21px;margin:8px 0}}p{{max-width:1000px}}a{{color:#1552a5}}article,.card{{background:white;border:1px solid #dbe2eb;border-radius:12px;padding:24px;margin:18px 0}}.eyebrow{{color:#576a80;font-size:13px;letter-spacing:.025em;margin:0}}.muted,small{{color:#576a80}}img{{max-width:100%;height:auto;background:white;border-radius:8px}}table{{border-collapse:collapse;width:100%;font-size:13px;background:white}}th,td{{text-align:left;border-bottom:1px solid #dbe2eb;padding:10px}}th{{background:#e9eff6}}.scroll{{overflow-x:auto}}code{{font-size:12px;overflow-wrap:anywhere}}summary{{cursor:pointer;color:#1552a5}}li{{margin:8px 0}}.lead{{font-size:20px}}@media print{{body{{background:white}}article{{break-inside:avoid}}details{{display:block}}}}
</style><main><p class="eyebrow">PHYS LITE BENCH · EXISTING NO-HINT SWEEP · ANALYSIS ONLY</p><h1>Most completed failures get calibration right and the new physics wrong</h1><p class="lead">Across the 15 complete settings, 186 of 191 normally completed failures passed calibration and parameter checks and failed only hidden predictions. DeepSeek has a different dominant problem: 105 execution errors in 117 attempts, with 101 submitted model files unchanged from their starters.</p>
<p>This report analyzes the existing Pareto sweep: <b>GPT-6 Luna, GPT-5.6 Terra, GPT-6 Sol, GPT-6 Astra and DeepSeek V4.1 Flash</b>. It is separate from the ongoing GPT-5.6 Luna / Terra / DeepSeek hint experiment. No new model calls were made, and no task, prompt, grading rule or recorded outcome was changed.</p>
<div class="card"><b>Coverage and evidence</b><p>All 588 recorded primary attempts were indexed and their saved final-source and trajectory hashes verified against the sweep manifest. The overview uses 585 attempts from 15 complete settings; the 3 DeepSeek None attempts remain a separate partial setting. Automated extraction covers tool actions, final-code structure, calibration/parameter metrics, failed test names and exception classes. Nine illustrative trajectories below received direct source-and-action review. Four received controlled in-memory physics corrections. Internal analysis messages are not reproduced or used as evidence.</p></div>
<h2>Where attempts failed</h2><img src="failure-breakdown.png" alt="Stacked counts separating completed passes, prediction-only failures, other verification failures, timeouts and other execution errors"><div class="scroll"><table><thead><tr><th>Model / effort</th><th>Pass</th><th>Prediction only</th><th>Other verification</th><th>Timeout</th><th>Other execution</th><th>Prediction failure with non-fit AST retained</th><th>Exact starter retained</th></tr></thead><tbody>{tr}</tbody></table></div>
<p class="muted">“Non-fit AST retained” is a conservative structural flag: after removing fit methods, imports and docstrings, the submitted Python syntax tree equals the starter. It is not a semantic proof, and an AST change does not imply that the physical model changed. Terra often rewrote validation or formatting while preserving the same approximation. Exact starter retention compares the complete file bytes.</p>
<h2>What the trajectories establish</h2><ul><li><b>Calibration is usually not the bottleneck.</b> Of 191 normal-completion failures, 186 (97.4%) are prediction-only failures. The other five are all Luna Low and include an unchanged unfinished fit or replacements that already fail calibration.</li><li><b>Public tests are insufficient to validate the extrapolation.</b> A tool-observation test-pass summary is present in at least 141 of those 186 prediction-only failures. All 81 normal Terra failures have such a summary. Missing summaries are not treated as evidence that tests were skipped.</li><li><b>Extra effort helps some models but is not monotonic.</b> Terra rises from 4 to 9 to 19 completed passes out of 39; Luna has 4, 1 and 12. These are small samples on selected tasks, and High includes reused observations; this is descriptive, not a causal estimate of effort.</li><li><b>DeepSeek’s 0/39 points do not isolate physics ability.</b> Low/High/Max have 24/26/33 timeouts, plus 9/8/5 other execution errors. Only 6/5/1 attempts complete normally; all 12 fail hidden predictions after fitting calibration. The 22 non-timeout failures include reviewed rate limits, stream closures and response-output limits. The exact cause of each timeout is not inferred from its exception alone.</li><li><b>Astra Extra High’s apparent drop is a time-budget effect in these records.</b> Both of its non-completed attempts have saved checkpoints that passed verification. They remain execution failures under the original completed-pass definition.</li></ul>
<h2>Four physical omissions tested directly</h2><p>Each calculation first reproduces the original saved hidden errors, then changes one physical ingredient in an in-memory copy while keeping the fitted parameter fixed. All tested prediction groups fall below their original limit after correction. These analyst-provided corrections diagnose the saved code; they are <b>not additional benchmark passes</b>.</p><img src="diagnostic-repairs.png" alt="Four saved failures have their group errors reduced below tolerance by targeted physical corrections"><div class="scroll"><table><thead><tr><th>Task</th><th>Largest error before</th><th>Largest error after</th><th>Isolated correction</th></tr></thead><tbody>{repair_rows}</tbody></table></div><p class="muted">Entropy, magnetic tracer and single-file calculations cover all hidden prediction groups. Reaction–diffusion covers its three fluctuation groups; its unchanged mean-transport solver is not rerun. Original group errors were reproduced within {max(r['max_original_metric_reproduction_difference'] for r in F['cases']):.2g}. This supports the stated failure location, without claiming a comprehensive verification of each altered implementation.</p>
<h2>Nine concrete solve trajectories</h2>{''.join(case_html)}
<h2>Implications for the ongoing hint comparison</h2><p>The useful mechanism to inspect is whether a physics hint changes the relevant equation, covariance or admissible solution branch before submission. More validation alone can preserve the wrong model, as the Terra examples show. For DeepSeek, separately track completion and whether it writes a usable model before the deadline. The current paired hint protocol stays frozen; this analysis does not change its prompts, resources or schedule.</p>
<h2>Limits and reproducibility</h2><ul><li>Three attempts per task/setting; tasks were selected during development against GPT-5.6 Luna. These counts are not population accuracy estimates.</li><li>120 High observations were reused from the earlier comparison. Four reused Terra High trials had documented host-sleep timing effects. Timing figures in individual cases are observed wall time, not pure reasoning time.</li><li>Root-cause attribution is limited to the reviewed cases. Automated “prediction-only failure” does not itself distinguish physics, mathematical and numerical mistakes.</li><li>Case selection is explanatory and post-hoc; cases are not a random sample. Recorded exceptions and all unsuccessful attempts remain in the denominators.</li><li>The partial DeepSeek None setting has 2 normal prediction failures and 1 timeout. The 36 unrun attempts are not treated as failures.</li><li>The first diagnostic-script run stopped on an assertion because the same reaction covariance expression appeared in both a public method and a compatibility helper. The corrected script accounts for both occurrences; no submission or outcome was altered.</li></ul>
<p><a href="../../results/trajectory-analysis-20261014/analysis.json">All 588 attempt records and extracted action metadata</a> · <a href="../../results/trajectory-analysis-20261014/diagnostic-repairs.json">Diagnostic calculations</a> · <a href="../../results/trajectory-analysis-20261014/case-reviews.json">Case review index</a> · <a href="failure-breakdown.pdf">Overview PDF</a> · <a href="diagnostic-repairs.pdf">Diagnostic PDF</a></p><p class="muted">Source: results/reasoning-sweep-20261011/results.json · SHA-256 {D['source_sha256']}<br>Analysis generated {esc(datetime.now(timezone.utc).isoformat())}. Original private reference notes and verifier data remain the physical baseline for this local audit.</p></main></html>'''
    (O/'report.html').write_text(report)
    for src,name in [('/private/tmp/analyze_physlite_trajectories.py','analyze.py'),('/private/tmp/diagnose_physlite_failures.py','diagnostic_repairs.py'),('/private/tmp/render_physlite_trajectory_report.py','render_report.py')]:
        (A/'tooling').mkdir(exist_ok=True);shutil.copy2(src,A/'tooling'/name)
    print(json.dumps({'report':str(O/'report.html'),'plots':[str(O/'failure-breakdown.png'),str(O/'diagnostic-repairs.png')],'reviewed_cases':len(enriched),'diagnostic_cases':len(F['cases'])},indent=2))

if __name__=='__main__':main()
